/* eslint-disable no-underscore-dangle */
import React, { useState, useMemo, useRef } from 'react';
import styled from 'styled-components';
import { Button, Skeleton } from 'antd';
import { useSelector } from 'react-redux';
import Router from 'next/router';

import {
  useFetchAppListById,
  useFetchNewProfile,
} from 'components/features/setting/useSettingPage';
import NewRequestQuoteForm from 'components/features/setting/Quote/PlanBasedPricingPopup/NewRequestQuoteForm';
import AppAddModalForm from 'components/features/setting/OrganizationSetting/AppSection/AppAddModalForm';
import { theme } from 'theme';
import AppDisplay from './AppDisplay';

const MainDiv = styled.div`
  width: 260px;
  display: flex;
  flex-direction: column;
  gap: 16px;
`;

const AppListWrapper = styled.div`
  overflow-y: auto;
  max-height: 340px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  background: transparent;
`;
const InnerDiv = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  .ant-btn {
    padding: 8px 18px;
    font-size: 12px;
    font-weight: 500;
    border-radius: 6px;
    border: 1px solid #E8E8EB;
    display: flex;
    align-items: center;
    justify-content: center;
    color: ${theme.colors.surface400.toString()};

    &:hover{
      color: ${theme.colors.primary500.toString()};
    }
  }
`;
const TitleDiv = styled.div`
  font-weight: 500;
  font-size: 14px;
  line-height: 16px;
  color: ${theme.colors.primary900.toString()};
`;

const AppMenuContent = (props) => {
  const {
    orgIndex,
    urlRouteTo,
    orgList,
    displayAppListPopover,
  } = props;
  const [requestQuoteVisible, showHideQuoteModal] = useState(false);
  const appRef = useRef();

  const {
    urlReducer: urlQuery,
    currentAppReducer: currentApp,
    currentOrgReducer: currentOrg,
  } = useSelector((state) => state);

  const currentAppId = urlQuery?.appId || currentApp?._id;

  const appList = orgList?.[orgIndex]?.apps;
  const menuOrgId = currentApp?.orgId || currentOrg?.orgId;
  const { isLoading, data: appListFromData } = useFetchAppListById(menuOrgId);
  useFetchNewProfile(`profileInfo`);

  const appListIds = useMemo(
    () =>
      Array.isArray(appListFromData)
        ? appListFromData.map((app) => app?._id)
        : [],
    [appListFromData]
  );

  const filterAppList = useMemo(
    () =>
      Array.isArray(appList)
        ? appList
            .filter((item) => appListIds.includes(item?._id))
            .sort((a, b) => {
              if (a?._id === currentAppId) return -1;
              if (b?._id === currentAppId) return 1;
              return 0;
            })
        : [],
    [appListIds, appList, currentAppId]
  );

  const navigateToAppTeam = () => {
    let url;
    let params;
    if (currentApp['_id']) {
      url = `/settings/org/${currentApp?.orgId}/apps`;
      params = `/integration?parentType=settings&setting=org_setting&org=${currentApp?.orgId}&org_tab=apps`;
    }
    displayAppListPopover(false);
    Router.push(params, url);
  };

  return (
    <MainDiv data-intercom-target="App Popup">
      <InnerDiv>
        <TitleDiv>My apps</TitleDiv>
        {
          filterAppList?.length > 0 &&  <div>
          <Button
            onClick={() => {
              navigateToAppTeam();
            }}
          >
            Manage apps
          </Button>
        </div>
        }
       
      </InnerDiv>
      <Skeleton loading={isLoading || !Array.isArray(appList)} active>
        <AppListWrapper ref={appRef}>
          {filterAppList?.length > 0 &&
            filterAppList.map((app, index) => (
              <div key={app?._id}>
                <AppDisplay
                  urlRouteTo={urlRouteTo}
                  // removeSessionDetailClass={removeSessionDetailClass}
                  app={app}
                  displayAppListPopover={displayAppListPopover}
                  initial={index === 0}
                  showHideQuoteModal={showHideQuoteModal}
                />
              </div>
            ))}
        </AppListWrapper>
      </Skeleton>

      <AppAddModalForm menuBar displayAppListPopover={displayAppListPopover}/>
      <NewRequestQuoteForm
        setShowPricingModal={showHideQuoteModal}
        showPricingModal={requestQuoteVisible}
      />
    </MainDiv>
  );
};

export default AppMenuContent;
