import React from 'react';
import { Tooltip } from 'antd';
import RightSideSVG from 'public/static/redesign/sidebar/right_expand.svg';
import styled from 'styled-components';
import { useSelector } from 'react-redux';
import ProfileImageOrText from 'components/features/setting/ProfileImageOrText';
import {
  useFetchRolesAndPermission,
  useFetchAppListById
} from 'components/features/setting/useSettingPage';
import { theme } from 'theme';
import AppMenuContent from './AppMenuContent';
import CommonPopover from './CommonPopover';

const StyledMainDiv = styled.div`
  display: flex;
  height: 36px;
  width: 100%;
  cursor: pointer;
  border-radius: 6px;
  background: ${theme.colors.surface10.toString()};
  align-items: center;
  padding: 0 6px;
  color: ${theme.colors.surface500.toString()};
  transition: color 0.2s ease-in-out;

  &.ant-popover-open {
    background-color: ${theme.colors.primary500.toString()};
    color: ${theme.colors.primarySnow.toString()};
    svg {
      fill: ${theme.colors.primarySnow.toString()};
    }
  }

  .anticon {
    margin-left: auto;
  }
  svg {
    min-width: 24px;
    width: 24px;
    min-height: 24px;
    fill: ${theme.colors.surface300.toString()};
    margin-left: auto;
  }

  &:hover:not(.ant-popover-open) {
    background-color: ${theme.colors.primary100.toString()};
    color: ${theme.colors.primary500.toString()};
    svg {
      fill: ${theme.colors.primary500.toString()};
    }
  }
`;

const StyledAppName = styled.div`
  display: flex;
  flex-direction: column;
  max-width: 108px;
  color: inherit;
  font-weight: 400;
  font-size: 14px;
  line-height: 16px;
  margin-left: 8px;
`;

const StyledName = styled.p`
  text-overflow: ellipsis;
  overflow: hidden;
  white-space: pre;
  color: inherit;
  margin: 0;
  padding: 0;
  width: 100%;
`;

const AppMenu = (props) => {
  const {
    collapsed,
    orgIndex,
    urlRouteTo,
    navigate,
    navigateToAppTeam,
    addSessionId,
    showAppList,
    displayAppListPopover,
  } = props;

  const { 
    currentOrgReducer: activeSubscription,
    urlReducer: urlQuery,
    currentAppReducer: currentApp,
    applicationReducer: orgList,
    currentOrgReducer: currentOrg,
    profileReducer: profile,
  } = useSelector(
    (state) => state
  );

  const {orgId} = activeSubscription || {}

  useFetchRolesAndPermission('roles_permission');
  useFetchAppListById(currentApp?.orgId || orgId);

  return (
    <CommonPopover
        placement="rightTop"
        collapsed={collapsed}
        content={
            <AppMenuContent
              orgIndex={orgIndex}
              urlRouteTo={urlRouteTo}
              orgList={orgList}
              currentApp={currentApp}
              navigate={navigate}
              navigateToAppTeam={navigateToAppTeam}
              currentOrg={currentOrg}
              profile={profile}
              addSessionId={addSessionId}
              urlQuery={urlQuery}
              displayAppListPopover={displayAppListPopover}
            />
        }
        trigger="click"
        visible={showAppList}
        onVisibleChange={displayAppListPopover}
        mouseEnterDelay={0.4}
      >
          <StyledMainDiv data-intercom-target="Sidebar App">
            <>
              <ProfileImageOrText
                picture={currentApp?.image}
                nameInfo={currentApp?.name}
                size={25}
                shape="square"
              />
              {!collapsed && (
                <StyledAppName>
                  <StyledName>
                    <Tooltip
                      title={
                        currentApp?.name?.length >= 10
                          ? currentApp?.name
                          : undefined
                      }
                      color="#fff"
                      overlayInnerStyle={{ color: '#000000d9', whiteSpace: 'pre' }}
                    >
                      {currentApp?.name}
                    </Tooltip>
                  </StyledName>
                  
                </StyledAppName>
              )}
            </>
            <RightSideSVG />
          </StyledMainDiv>
      </CommonPopover>
  );
};

export default AppMenu;
