/* eslint-disable no-underscore-dangle */
import React, { useRef, memo, useEffect, useMemo } from 'react';
import styled from 'styled-components';
import { Button } from 'antd';
import { useSelector, useDispatch } from 'react-redux';
import Router from 'next/router';
import Link from 'next/link';

import UserImageInfo from 'components/features/setting/ProfileImageOrText';
import TextTruncated from 'components/common/TextTruncated';
import { checkPlanStatus } from 'redux/actions/accessManagement';
import { changeCommonValue } from 'redux/actions/common';
import { resetFilterV2 } from 'redux/actions/filter';
import { hasAccessFalseIcon } from 'Utils/constants/index';
import { lastAppSelected } from 'redux/actions/appdropdown';
import { getActiveSubscription } from 'redux/actions/subscription';
import { theme } from 'theme';
import { LockIcon } from 'public/static/redesign/sidebar';
import { useFeatureFlag } from 'uxcam-frontend-components';
import ExportDataButton from './ExportButton';

// Parent types that should default to 'overview'
const DEFAULT_TO_OVERVIEW_TYPES = ['settings', 'integration', 'dashboard'];

const SESSION_PARENT_TYPE_MAP = {
  sessionsList: 'aiSessionsList',
  sessionStatistics: 'aiSessionStatistics',
};

const SESSION_ROUTE_MAP = {
  sessionsList: 'aisessions/list',
  sessionStatistics: 'aisessions/analytics',
};

const AppDiv = styled.div`
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  background: ${({ isactive }) =>
    isactive ? '#EFF5FF' : '#ffffff'};
  border-radius: 6px;
  border: 1px solid;
  border-color: ${({ isactive }) => (isactive ? '#fff' : '#E8E8EB')};
  cursor: pointer;
  :hover {
    border-color: #5d97ff;
  }

  .ellipse-tooltip-text {
    font-weight: ${({ isactive }) => (isactive ? '500' : '400')} !important;
  }
`;

const ImgTextDiv = styled.div`
  display: flex;
  align-items: center;
  gap: 10px;
  .anticon {
    margin-bottom: 12px;
    font-size: 8px;
  }
  svg {
    width: 24px;
    height: 24px;
    fill: ${theme.colors.surface400.toString()}
  }
`;

const ActiveDiv = styled.div`
  display: flex;
  gap: 8px;

  a {
    display: flex;
    width: 100%;
    justify-content: center;
    align-items: center;
  }

  button {
    flex: 1;
  }
`;

const StyledButton = styled(Button)`
  padding: 8px 0px;
  font-size: 12px;
  font-weight: 500;
  border-radius: 6px;
  border: 1px solid #E8E8EB;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: none;
  min-width: 100px;
  color: ${theme.colors.surface400.toString()};
  :hover {
    border-color: #E8E8EB;
    color: #5d97ff;
  }
`;

const LinkButton = styled(Button)`
  color: #5d97ff;
  padding: 0;
  height: 0;
  border: none;
`;

const AppTypeIcon = styled.img`
  pointer-events: none;
  width: 24px;
  height: 24px;
`

const AppNameWrapper = styled.div`
  display: flex;
  max-width: 100%;
  width: 100%;
  justify-content: space-between;
  overflow: hidden;
  gap: ${ theme.spacing( 2 ) };
`

const AppDisplay = (props) => {
  const {
    urlRouteTo,
    app,
    displayAppListPopover,
    initial,
    showHideQuoteModal,
  } = props;

  const dispatch = useDispatch();

  const {
    accessManagement,
    urlReducer: urlQuery,
    currentAppReducer: currentApp,
    currentOrgReducer: currentOrg,
  } = useSelector((state) => state);
  const appRef = useRef();

  const keyValueDispatcher = (key, value, message) =>
    dispatch(changeCommonValue(key, value, message));

  const isWebOrg = useFeatureFlag( 'app-settings-domains' );

  const currentAppId = urlQuery?.appId || currentApp?._id;
  const { hasAccess, _id: appId, isIntegrated, name, image, appType } = app;
  const { orgId } = currentOrg || {};

  const appCount = currentOrg?.planLimit?.appCount;

  const { planStatus } = accessManagement;
  const isPlanActionNeededOne =
    planStatus?.selectAppAction || planStatus?.selectUserAction;
  const currentParentType = urlQuery?.parentType;

  const queryPType = useMemo(() => {
    if (!currentParentType || DEFAULT_TO_OVERVIEW_TYPES.includes(currentParentType)) {
      return 'overview';
    }

    if (currentParentType in SESSION_PARENT_TYPE_MAP) {
      return SESSION_PARENT_TYPE_MAP[currentParentType];
    }

    return currentParentType;
  }, [currentParentType]);

  const adjustedUrlRouteTo = useMemo(() => {
    if (currentParentType in SESSION_ROUTE_MAP) {
      return SESSION_ROUTE_MAP[currentParentType];
    }
    return urlRouteTo;
  }, [currentParentType, urlRouteTo]);

  const asHref = isIntegrated
    ? `/app/${appId}/${adjustedUrlRouteTo}`
    : `/integration?appId=${appId}`;

  const queryObj = `appId=${appId}&parentType=${
    isIntegrated ? queryPType : 'integration'
  }&eventpage=${
    currentParentType === 'eventsList' ? '&eventpage=1' : ''
  }&issueType=${currentParentType === 'issues' ? 'crashes' : ''}`;

  const handleAppClick = async (e) => {
    e.preventDefault();
    displayAppListPopover(false);
    if (hasAccess && !isPlanActionNeededOne) {
      keyValueDispatcher('isVisible_custom_popup', false, null);
      try {
        localStorage.setItem('appId', appId);
      } catch (err) {
        // silent fail
      }
      // removeSessionDetailClass();
      dispatch(resetFilterV2());
      dispatch(checkPlanStatus(orgId))
        .then((res) => {
          const isPlanActionNeeded =
            res?.selectAppAction || res?.selectUserAction;
          isPlanActionNeeded &&
            Router.push(
              `/integration?parentType=plan-downgrade&appId=${appId || ''}${
                orgId ? `&orgId=${orgId}` : ''
              }`,
              `/plan-downgrade?appId=${appId || ''}${
                orgId ? `&orgId=${orgId}` : ''
              }`
            );
        })
        .catch((err) => err);
      dispatch(lastAppSelected(appId));
    }

    if (!hasAccess)
      keyValueDispatcher(
        'isVisible_custom_popup',
        true,
        <span>
          <h3>
            {`Your current plan includes ${appCount} app environment${appCount > 1 ? 's' : ''
              }`}
            .
          </h3>
          <p>
            To gain access to additional apps, please{' '}
            <LinkButton
              type="link"
              onClick={() => {
                showHideQuoteModal(true);
                keyValueDispatcher('isVisible_custom_popup', false, '');
              }}
            >
              request a quote
            </LinkButton>{' '}
            to upgrade your account.
          </p>
        </span>
      );

    if (hasAccess) {
      dispatch(getActiveSubscription(orgId)).then(() =>
        Router.push(`/integration?${queryObj}`, asHref)
      );
    }
  };

  const executeScroll = () => appRef?.current?.scrollIntoView(true);

  useEffect(() => {
    appRef?.current && executeScroll();
  }, [appRef?.current]);


  return (
    <AppDiv
      isactive={currentAppId === appId}
      key={appId}
      onClick={(e) => {
        appId !== currentAppId && handleAppClick(e);
      }}
      ref={initial ? appRef : null}
    >
      <ImgTextDiv>
        <div>
          <UserImageInfo
            picture={image}
            nameInfo={name || ''}
            size={36}
            shape="square"
          />
        </div>
        { isWebOrg ? (
        <AppNameWrapper>
          <TextTruncated value={name} />
          { appType === 'web' ? (
            <AppTypeIcon src="/static/web-app.svg" alt="web-app" />
          ) : null }
          { appType === 'mobile' ? (
            <AppTypeIcon src="/static/mobile-app.svg" alt="web-app" />
          ) : null}
        </AppNameWrapper>
        ) : (
          <TextTruncated value={name} />
        ) }
        {!hasAccess && <LockIcon />}
      </ImgTextDiv>

      {currentAppId === appId && (
        <ActiveDiv>
          <StyledButton
            onClick={() => displayAppListPopover(false)}
            data-intercom-target="App settings"
          >
            <Link
              href={{
                pathname: '/integration',
                query: {
                  parentType: 'settings',
                  setting: 'app_setting',
                  org: orgId,
                  app: appId,
                  app_tab: 'video_recording_setting',
                },
              }}
              as={`/settings/app/${orgId}/${appId}${'/video_recording_setting'}`}
              passHref
            >
              App settings
            </Link>
          </StyledButton>

          <ExportDataButton
            hasAccessOrg={hasAccess}
            keyValueDispatcher={keyValueDispatcher}
            displayAppListPopover={displayAppListPopover}
          />
        </ActiveDiv>
      )}
    </AppDiv>
  );
};

export default memo(AppDisplay);
