import React, { useEffect, useMemo, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Modal, Button, message, Checkbox, DatePicker } from 'antd';
import { isString } from 'underscore';
import styled from 'styled-components';
import { useQueryClient } from 'react-query';
import moment from 'moment/moment';

import { rollbar } from 'components/common/rollbar';
import { fetchPlanHatApi } from 'redux/actions/common';
import {
  useExportData,
} from 'components/features/setting/useSettingPage';

import { useCheckExportPlan } from 'hooks/useCheckExportPlan';
import { theme } from 'theme';
import { useIsAppType } from 'hooks/useIsAppType';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';


const { RangePicker } = DatePicker;
const dateFormat = 'YYYY-MM-DD';

const createExportOptions = (noCodeEventsEnabled) => [
  {
    label: 'Sessions',
    value: 'sessions',
  },
  {
    label: 'Users',
    value: 'users',
  },
  ...(noCodeEventsEnabled 
    ? [
        { label: 'Coded events', value: 'events' },
        { label: 'Smart events', value: 'no_code_event' }
      ]
    : [{ label: 'Events', value: 'events' }]
  ),
  {
    label: 'Screens',
    value: 'screens',
  },
];

const MainWrapper = styled.div`
  .export-data-res-loader {
    padding-bottom: 70px;
    position: absolute;
    margin: auto;
    left: 0;
    right: 0;
    top: 0;
    bottom: 0;
  }
  .download-box {
    .ant-checkbox-group {
      width: 100%;
    }
    .date-rangepicker {
      margin-top: 20px;
    }
    .response-text {
      padding-bottom: 25px;
    }
  }

  .limit-message-box {
    text-align: center;
  }
  .limit-message-box .modal-header {
    text-align: left;
    border-bottom: 1px solid #e6e6e6;
    margin-left: -15px;
    margin-right: -15px;
    padding: 0 15px 5px;
  }
  .data-request-failure {
    text-align: center;
  }
  .limit-message-box .modal-body {
    padding: 30px 0;
  }
  .limit-message-box .modal-body p {
    font-size: 14px;
  }
  .limit-message-box .modal-footer a {
    line-height: 35px;
    margin: 0 10px;
  }
`;
const StyledParagraph = styled.p`
  line-height: normal;
`;
const StyledHeading = styled.h3`
  margin-bottom: 8px !important;
`;
const StyledPTag = styled.p`
  color: ${({ key }) => (key === 'success' ? 'green' : 'red')};
`;

const ButtonWrapper = styled(Button)`
  padding: 8px 0;
  font-size: 12px;
  font-weight: 500;
  border-radius: 6px;
  border: 1px solid #E8E8EB;
  display: flex;
  align-items: center;
  justify-content: center;
  color: ${theme.colors.surface400.toString()};

  :hover {
    border-color: #E8E8EB;
    color: #5d97ff;
  }
`;
const text = (
  <span key="error-span">
    <StyledPTag key="error-p">
      Sorry, we are unable to process your request! Please try again later
    </StyledPTag>
  </span>
);

const defaultOneMonth = { lower: moment().subtract(1, 'months').utcOffset(0).startOf('day').format(), upper: moment().utcOffset(0).endOf('day').format() }

const ExportDataButton = (props) => {
  const dispatch = useDispatch();
  const queryClient = useQueryClient();
  const { hasAccessOrg, keyValueDispatcher, displayAppListPopover } = props;

  const {canExportData, isApiError, apiError, CommonUpgradeModal, upgradePlan, setUpgradePlan} = useCheckExportPlan();

  const [visibleDownloadModal, setVisibleDownloadModal] = useState(false);
  const [display, setDisplay] = useState(false);
  const [tableList, setTableList] = useState([]);
  const [customDateRange, setCustomDateRange] = useState([]);
  const [resText, setResText] = useState('');
  const [isExportDataRequested, setIsExportDataRequested] = useState();

  const { currentAppReducer: currentApp, profileReducer } = useSelector(
    (state) => state
  );
  const {noCodeEventsFeatureFlag} = useNoCodeEventsContext() 

  const { _id: appId, isIntegrated } = currentApp;

  const exportOptions = useMemo(() => 
    createExportOptions(noCodeEventsFeatureFlag), 
    [noCodeEventsFeatureFlag]
  );
  const { email } = profileReducer;
  
  const handleDateChange = (val) => { 
     setCustomDateRange({ lower: moment(val[0]).utcOffset(0).startOf('day').format(), upper: moment(val[1]).utcOffset(0).endOf('day').format() });
  };


  const handleCheckboxChange = (checkedValues) => {
    setTableList(checkedValues);
  };

  const showDownloadModal = (e) => {
    e.preventDefault();
    if (canExportData) {
      setVisibleDownloadModal(true);
      setDisplay(true);
    } else {
      setUpgradePlan(true);
    }
  };

  const isWebApp = useIsAppType('web');

  const payload = {
    name: 'get_csv_dump',
    appid: appId,
    email_id: email,
    table_list: tableList,
    date_range: {
      attribute: 'date_range',
      operator: 'between_dates',
      value: customDateRange,
    },
    webApp: isWebApp || false,
  };
  const exportQueryKey = useMemo(() => `export-${appId}`, [appId]);
  const {
    data: exportData,
    refetch: downloadData,
    isLoading,
  } = useExportData(payload, exportQueryKey);

  const downloadRequest = () => {
    downloadData()
      .then((res) => {
        if (res?.data?.success) {
          if (isString(res?.data) || !res?.data?.success) {
            setResText(text);
          } else {
            dispatch(fetchPlanHatApi({ action: 'Export CSV' }));
          }
        } else {
          rollbar.error(res && `${res?.data} [ DATA CSV DOWNLOAD ]`);
          setResText(text);
        }
      })
      .catch((err) => {
        rollbar.error(err && `${err?.response} [ DATA CSV DOWNLOAD ]`);
        const errorText = (
          <span key="error-catch-span">
            <StyledPTag key="error-catch-p">
              {err?.response?.data?.error?.message ||
                'Error, please try again after a few minutes'}
            </StyledPTag>
          </span>
        );
        setResText(errorText);
      });
  };

  const handleDownloadRequest = (e) => {
    e.preventDefault();

    if (tableList?.length <= 0) {
      message.info('Select an option');
      return;
    }
    setIsExportDataRequested(true);
    downloadRequest();
  };

  const cancelDownloadBtn = () => {
    setVisibleDownloadModal(false);
    setDisplay(false);
    setTableList([]);
    setIsExportDataRequested(false);
    setCustomDateRange([]);
    setResText('');
    queryClient.setQueryData(exportQueryKey, {});
  };

  const handleApiData = async (e) => {
    e.preventDefault();
    if (apiError?.response?.data?.error || isApiError) {
      message.error(
        apiError?.response?.data?.error?.message || 'Something went wrong'
      );
      return;
    }

    showDownloadModal(e);
  };

  useEffect(()=>{
    visibleDownloadModal && setCustomDateRange(defaultOneMonth)
  }, [visibleDownloadModal])

  return (
    <>
    {isIntegrated ? 
      <ButtonWrapper
        // icon={<UploadOutlined />}
        onClick={(e) => {
          if (typeof hasAccessOrg === 'boolean') {
            if (hasAccessOrg) {
              handleApiData(e);
            } else
              keyValueDispatcher(
                'isVisible_custom_popup',
                true,
                `As your current plan limit has exceeded, access to the feature is revoked.`
              );
          } else handleApiData(e);
          displayAppListPopover(false);
        }}
      >
        Export data
      </ButtonWrapper> : null}
      {
        upgradePlan && <CommonUpgradeModal />
      }      
      <Modal
        visible={visibleDownloadModal}
        title="Export Data"
        width={530}
        onCancel={() => cancelDownloadBtn()}
        footer={[
          !isExportDataRequested ? (
            ((
              <Button key="back" onClick={() => cancelDownloadBtn()}>
                Cancel
              </Button>
            ),
            (
              <Button
                key="submit"
                type="primary"
                loading={isLoading}
                onClick={(e) => handleDownloadRequest(e)}
              >
                Request data
              </Button>
            ))
          ) : (
            <Button
              key="btn-cancel"
              type="primary"
              onClick={(e) => cancelDownloadBtn(e)}
            >
              Got it!
            </Button>
          ),
        ]}
      >
        {display && (
          <MainWrapper>
            {!isExportDataRequested ? (
              <div className="download-box">
                <h3>
                  Download the raw data recorded from your sessions, events,{' '}
                  users and screens in CSV format.
                </h3>
                <p>
                  If you have questions regarding the data format or need the
                  data in another format, please get in touch with{' '}
                  <a href="mailto:team@uxcam.com">team@uxcam.com</a>
                </p>
                <Checkbox.Group
                  options={exportOptions}
                  value={tableList}
                  onChange={handleCheckboxChange}
                />
                <div className="date-rangepicker">
                  <span>
                    <b> {`Select a date range (optional): `}</b>
                    <RangePicker
                      onChange={handleDateChange}
                      format={dateFormat}
                      popupStyle={{ zIndex: '999999' }}
                    />
                  </span>
                </div>
              </div>
            ) : (
              <div
                className={`${
                  isExportDataRequested
                    ? 'data-request-box'
                    : 'data-request-failure'
                } `}
              >
                <div>
                  <div>
                    {!exportData?.error && isExportDataRequested && (
                      <StyledHeading>
                          Your data is on its way, check your mail
                        </StyledHeading>
                    )}

                    <div className="response-text">
                      {exportData?.error ? resText : ''}
                    </div>

                    {!exportData?.error && isExportDataRequested && (
                      <StyledParagraph>
                        It might take some minutes to prepare your data, but we
                        will send you a link to the csv files via email once
                        it&apos;s ready.
                      </StyledParagraph>
                    )}
                  </div>
                </div>
              </div>
            )}
          </MainWrapper>
        )}
      </Modal>
    </>
  );
};

export default ExportDataButton;
